import{_ as t,o as r,c as n,a5 as s}from"./chunks/framework.BjM_ivYE.js";const g="/RBQ/images/app/dashboard.pc.ko.png",p=JSON.parse('{"title":"대시보드","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/dashboard.md","filePath":"ko/manual/gui/dashboard.md","lastUpdated":1790646319000}'),a={name:"ko/manual/gui/dashboard.md"};function l(e,o,i,d,h,u){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="대시보드" tabindex="-1">대시보드 <a class="header-anchor" href="#대시보드" aria-label="Permalink to &quot;대시보드&quot;">​</a></h1><p>허브의 <code>대시보드</code> 타일로 <strong>대시보드</strong>를 엽니다. 이 타일은 로봇이 연결된 뒤에 눌립니다. 로봇의 실시간 상태를 카드로 보여 주고, 개발자 모드에서는 탭이 더 생겨 로봇 상태표까지 볼 수 있습니다.</p><p><img src="'+g+'" alt="대시보드 요약"></p><h2 id="요약-카드" tabindex="-1">요약 카드 <a class="header-anchor" href="#요약-카드" aria-label="Permalink to &quot;요약 카드&quot;">​</a></h2><h3 id="시스템" tabindex="-1">시스템 <a class="header-anchor" href="#시스템" aria-label="Permalink to &quot;시스템&quot;">​</a></h3><ul><li><strong>로봇 S/N</strong> — 지금 보고 있는 로봇의 시리얼 번호. 카드 맨 위에 있습니다. 연결되어 있지 않거나 로봇 소프트웨어가 오래된 버전이면 <code>—</code> 로 표시됩니다.</li><li><strong>배터리</strong> — 잔량 %와 팩 전압, 그리고 상태 문구: <ul><li><strong>정상</strong></li><li><strong>부족</strong> — 15 % 미만</li><li><strong>저전압 위험 — 즉시 충전</strong> — 10 % 미만이면서 팩 전압이 47 V 미만. 숫자가 빨갛게 바뀝니다. 작업을 멈추고 충전하세요.</li><li><strong>신호 없음</strong> — 배터리 데이터를 받지 못함(예: 시뮬레이션).</li></ul></li><li><strong>로봇 헬스</strong> — <strong>IMU</strong>, <strong>CAN</strong>, <strong>FindPose</strong>, <strong>Control</strong> 각각 <strong>정상</strong> 또는 <strong>점검</strong>. 모두 정상이면 카드 배지가 <strong>OK</strong>, 아니면 <strong>점검</strong>입니다.</li><li><strong>로봇 PC 상태</strong> — <strong>CPU</strong> 사용률 바, <strong>온도</strong>, <strong>MEM</strong> 바, <strong>스로틀</strong>(<strong>정상</strong> / <strong>발생</strong>).</li><li><strong>주행거리 (TRIP)</strong> — <strong>Total</strong>, <strong>Trip A</strong>, <strong>Trip B</strong>(m)와 <strong>A 리셋</strong> / <strong>B 리셋</strong> 버튼.</li></ul><h3 id="관절·자세" tabindex="-1">관절·자세 <a class="header-anchor" href="#관절·자세" aria-label="Permalink to &quot;관절·자세&quot;">​</a></h3><ul><li><strong>자세</strong> — 인공 수평의 다이얼과 <strong>Roll / Pitch / Yaw</strong>(설정에서 자이로 위젯을 켠 경우에만), <strong>GAIT_ID</strong>, <strong>낙상</strong>(<strong>정상</strong> 또는 <strong>FALL</strong>), <strong>RPY (°)</strong>, <strong>높이</strong>(m), <strong>배터리A</strong>(팩 전류).</li><li>배지는 제어 링크 상태를 알려 줍니다: <strong>LIVE</strong>, <strong>연결중</strong>, <strong>끊김</strong>.</li></ul><h3 id="구성" tabindex="-1">구성 <a class="header-anchor" href="#구성" aria-label="Permalink to &quot;구성&quot;">​</a></h3><ul><li><strong>PAYLOAD</strong> — <strong>장착 슬롯</strong>, <strong>총 질량</strong>, <strong>무게중심 X / Y / Z</strong>. 이어서 장착 장비가 각각 <strong>정상</strong> 또는 <strong>미감지</strong>로 나옵니다: <strong>로봇팔</strong>, <strong>PTZ</strong>. RAPID 사양 로봇에서는 <strong>RCWS</strong>, <strong>RCGS</strong>, <strong>CCTV</strong> 가 더 나옵니다.</li><li><strong>SENSOR</strong> — <strong>IMU</strong>, <strong>전방 카메라</strong>, <strong>후방 카메라</strong>, <strong>배면 카메라 0</strong> ~ <strong>3</strong>, <strong>IR</strong>, <strong>Depth</strong>, <strong>IR프로젝터</strong> 각각 <strong>정상</strong> 또는 <strong>미감지</strong>.</li></ul><p><strong>방사선 (KHNP)</strong> 카드는 KHNP 사양 로봇에서만 나타납니다.</p><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/ko/manual/gui/developer-mode.html#dashboard">개발자 모드</a>에 모아 두었습니다.</p></blockquote><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li>이 값들에 영향을 주는 경고·오류는 <a href="/RBQ/ko/manual/gui/logs.html">로그</a>에 모입니다.</li></ul>',14)])])}const m=t(a,[["render",l]]);export{p as __pageData,m as default};
